/**
 * Uniform response envelope of every endpoint, including error outcomes:
 * {@code {"code": <int>, "message": <string>, "data": <object|array|null>}}.
 *
 * <p>{@code code} carries the semantic status — {@code 200} for success and {@code 400} /
 * {@code 401} / {@code 403} / {@code 404} / {@code 500} for the documented error outcomes, in
 * which case {@code data} is {@code null}. Successful responses without an endpoint specific
 * message carry {@value #MESSAGE_SUCCESS}.</p>
 *
 * @param <T> type of the payload carried in {@code data}
 */
public class ApiResponse<T> {

    /** Semantic status of a successful outcome. */
    public static final int CODE_SUCCESS = 200;

    /** Semantic status of a malformed or rejected request. */
    public static final int CODE_BAD_REQUEST = 400;

    /** Semantic status of a missing or invalid authentication. */
    public static final int CODE_UNAUTHORIZED = 401;

    /** Semantic status of an authenticated but insufficiently privileged caller. */
    public static final int CODE_FORBIDDEN = 403;

    /** Semantic status of an unknown resource. */
    public static final int CODE_NOT_FOUND = 404;

    /** Semantic status of an unexpected server side failure. */
    public static final int CODE_INTERNAL_ERROR = 500;

    /** Default message of a successful response. */
    public static final String MESSAGE_SUCCESS = "success";

    private int code;
    private String message;
    private T data;

    public ApiResponse() {
    }

    public ApiResponse(int code, String message, T data) {
        this.code = code;
        this.message = message;
        this.data = data;
    }

    /** Successful response without payload and with the default {@code success} message. */
    public static <T> ApiResponse<T> success() {
        return new ApiResponse<>(CODE_SUCCESS, MESSAGE_SUCCESS, null);
    }

    /** Successful response carrying {@code data} with the default {@code success} message. */
    public static <T> ApiResponse<T> success(T data) {
        return new ApiResponse<>(CODE_SUCCESS, MESSAGE_SUCCESS, data);
    }

    /** Successful response carrying an explicit message and {@code data} (which may be null). */
    public static <T> ApiResponse<T> success(String message, T data) {
        return new ApiResponse<>(CODE_SUCCESS, message, data);
    }

    /** Error response with semantic {@code code}, the given message and a {@code null} payload. */
    public static <T> ApiResponse<T> error(int code, String message) {
        return new ApiResponse<>(code, message, null);
    }

    public int getCode() {
        return code;
