 * <p>The envelope carries the semantic status in {@code code}; the HTTP status of these rendered
 * outcomes stays 200, while the authentication filter answers its own rejections with HTTP 401.</p>
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    /** Message of the catch-all outcome; it never echoes internals back to the caller. */
    public static final String MESSAGE_INTERNAL_ERROR = "服务器内部错误";

