package com.cloudmart.platform.exception;

import com.cloudmart.platform.dto.ApiResponse;
import com.cloudmart.platform.service.OrderService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * Converts exceptions that escape controller handling into the uniform envelope.
 *
 * <ul>
 *   <li>{@link IllegalArgumentException} → code 400 with the exception message;</li>
 *   <li>{@link SecurityException} → code 403 with the exception message;</li>
 *   <li>{@link OrderService.OrderException} → the semantic code and message it carries, so that an
 *       order outcome surfacing outside its controller still renders correctly;</li>
 *   <li>any other exception → code 500 with {@value #MESSAGE_INTERNAL_ERROR}.</li>
 * </ul>
 *
 * <p>The envelope carries the semantic status in {@code code}; the HTTP status of these rendered
 * outcomes stays 200, while the authentication filter answers its own rejections with HTTP 401.</p>
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    /** Message of the catch-all outcome; it never echoes internals back to the caller. */
    public static final String MESSAGE_INTERNAL_ERROR = "服务器内部错误";

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    /** Rejected argument → 400 with the exception's own message. */
    @ExceptionHandler(IllegalArgumentException.class)
    public ApiResponse<Void> handleIllegalArgument(IllegalArgumentException e) {
        log.warn("Bad request: {}", e.getMessage());
        return ApiResponse.error(ApiResponse.CODE_BAD_REQUEST, e.getMessage());
    }

    /** Missing privilege → 403 with the exception's own message. */
    @ExceptionHandler(SecurityException.class)
    public ApiResponse<Void> handleSecurity(SecurityException e) {
        log.warn("Forbidden: {}", e.getMessage());
        return ApiResponse.error(ApiResponse.CODE_FORBIDDEN, e.getMessage());
    }

    /** Order outcome that reached the advice → the code and message it carries. */
    @ExceptionHandler(OrderService.OrderException.class)
    public ApiResponse<Void> handleOrderException(OrderService.OrderException e) {
        log.warn("Order operation rejected with code {}: {}", e.getCode(), e.getMessage());
        return ApiResponse.error(e.getCode(), e.getMessage());
    }

    /** Anything else → 500 with a generic message; the cause stays in the server log. */
    @ExceptionHandler(Exception.class)
    public ApiResponse<Void> handleUnexpected(Exception e) {
        log.error("Unhandled exception while serving request", e);
        return ApiResponse.error(ApiResponse.CODE_INTERNAL_ERROR, MESSAGE_INTERNAL_ERROR);
    }
}

package com.cloudmart.platform.mapper;

import com.cloudmart.platform.model.AuditLog;
import org.apache.ibatis.annotations.Insert;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Options;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;

import java.util.List;

/**
 * MyBatis mapper for the {@code audit_logs} table.
 *
 * <p>Every statement binds caller supplied values through {@code #{}} placeholders, i.e. as
 * JDBC prepared-statement parameters — never by string concatenation into the SQL text. List
 * queries return rows newest first; {@code id} breaks ties between rows sharing the same
 * second-resolution {@code created_at}.</p>
 */
@Mapper
public interface AuditLogMapper {

    /** Columns shared by every select below. */
    String COLUMNS = "id, user_id, action, resource_type, resource_id, detail, created_at";

    /** Newest-first ordering shared by the list queries. */
    String NEWEST_FIRST = " ORDER BY created_at DESC, id DESC";

    /** Inserts an audit row and back-fills the generated primary key onto {@code auditLog.id}. */
    @Insert("INSERT INTO audit_logs (user_id, action, resource_type, resource_id, detail, "
            + "created_at) VALUES (#{userId}, #{action}, #{resourceType}, #{resourceId}, "
            + "#{detail}, #{createdAt})")
    @Options(useGeneratedKeys = true, keyProperty = "id")
    int insert(AuditLog auditLog);

    /** All audit rows of one user, newest first. */
    @Select("SELECT " + COLUMNS + " FROM audit_logs WHERE user_id = #{userId}" + NEWEST_FIRST)
    List<AuditLog> findByUserId(@Param("userId") Long userId);

    /** All audit rows of all users, newest first. */
    @Select("SELECT " + COLUMNS + " FROM audit_logs" + NEWEST_FIRST)
    List<AuditLog> findAll();
}

