    String NEWEST_FIRST = " ORDER BY created_at DESC, id DESC";

    /** Inserts an order and back-fills the generated primary key onto {@code order.id}. */
    @Insert("INSERT INTO orders (order_no, user_id, product_id, duration_months, quantity, "
            + "total_price, status, created_at, expire_at) VALUES (#{orderNo}, #{userId}, "
            + "#{productId}, #{durationMonths}, #{quantity}, #{totalPrice}, #{status}, "
            + "#{createdAt}, #{expireAt})")
